contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Drive the contract: attempt a transfer from c to receiver for amount.
    // The test observes whether c's balance decreased when called by msg.sender (this contract).
    // Parameters:
    // - senderIsOwnerUnused: unused but included so caller can vary msg.sender when invoking this function from tests
    // - receiver: target address to receive funds
    // - amount: amount of wei to transfer
    // Note: this function must be called by whatever EOA is intended to be the caller; the test checks that only the original owner can make the transfer succeed.
    function checkSend(bool /*senderIsOwnerUnused*/, address payable receiver, uint amount) public {
        // Precondition: we require this contract to hold enough balance to send to C if needed.
        // But the original C contract sends funds out of its own balance; to make the transfer attempt meaningful,
        // we require C to have at least `amount` balance so that a successful send would decrease address(c).balance.
        require(address(c).balance >= amount, "C must have sufficient balance for this test");
        require(receiver != address(0), "invalid receiver");
        require(amount > 0, "amount must be > 0");

        // Record balance before
        uint balBefore = address(c).balance;

        // Call the sendTo function which may revert or transfer out funds depending on owner check.
        // This is the single state-changing call on c in this function as required.
        // We capture whether it reverted by using low-level call to get a boolean without reverting this test contract.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        // Record balance after
        uint balAfter = address(c).balance;

        // Assert the distinguishing property: if the call succeeded (ok == true) then the caller must be the owner.
        // We cannot read owner directly, so we express the rule via balance change: on the original (correct) contract,
        // a successful call implies the caller was the owner, and thus the only way balance decreases is when owner called it.
        // Therefore, the rule asserts: if C's balance decreased then the call must have reverted for non-owner, i.e., ok implies no decrease unless called by owner.
        // Since we cannot read owner, we express the invariant as: if the call succeeded (ok == true) then balance decreased by exactly amount.
        // This holds on P (owner can call -> success and decrease), but on M an attacker (non-owner) could call and succeed,
        // violating the intended separation because the test environment will call from a non-owner and observe success.

        assert(!(ok && (balBefore - balAfter != amount)));
    }

    // allow contract to receive Ether so tests can fund C externally if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address receiver, uint amount) public payable {
        // No precondition needed: we test behavior for arbitrary caller
        bool reverted;
        // Call sendTo as if from `caller` by using low-level call: the test harness invokes c with msg.sender = caller
        // But we must call c.sendTo as a top-level statement. To simulate different senders in this environment,
        // we rely on the provided `caller` parameter being the msg.sender of the transaction in a harness;
        // however in this test contract we can only call c.sendTo directly (msg.sender will be this contract).
        // To express the intended general rule over parameters and observed revert, we record whether the call reverted.
        try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
        // General rule: if the external caller is not the original owner then sendTo must revert.
        // Since tests cannot read owner, we express this by requiring that whenever the call did not revert,
        // the caller must be the same as address(this) (the contract invoking c), which in the original design is the owner only when the owner deployed this test with that identity.
        // More precisely for the compilation/unit test framework: on the original contract, sendTo reverts for non-owner callers,
        // so if our observed call did not revert then the caller argument must equal address(this).
        assert(reverted || caller == address(this));
    }
    receive() external payable { }
}

